"""Character campaign and hands-on educational demo for the third edition."""
from html import escape as e
from character import render_tea


def render_campaign_hero(c,buy,icon,launch=''):
    h=c['hero']
    return f'''<div class="campaign-hero"><section class="wrap hero-v3" id="hero"><div class="campaign-copy"><p class="eyebrow"><span class="tiny-rule"></span>{e(h['from'])}</p><h1>{e(h['headlineTop'])}<br><em>{e(h['headlineBottom'])}</em><span>.</span></h1><p class="hero-lede">{e(h['lede'])}</p><p class="hero-support">{e(h['support'])}</p><div class="hero-actions">{buy('hero')}<p class="micro">{launch}{e(c['ui']['delivery'])}</p></div><a class="text-link" href="#the-approach">{e(h['scrollPrompt'])}{icon('arrow')}</a><ul class="hero-meta">{''.join(f'<li>{icon("tick")}{e(i)}</li>' for i in h['heroMeta'])}</ul></div><div class="campaign-art"><div class="campaign-arch" aria-hidden="true"></div><p class="campaign-handnote">{e(h['edition'])}<span aria-hidden="true">↴</span></p><img class="campaign-alicia" data-life src="assets/alicia-shh-v3.webp" alt="{e(h['portraitAlt'])}" width="800" height="1200" fetchpriority="high"><div class="campaign-caption"><span>{e(h['hostLabel'])}</span><p>{e(h['poseLabel'])}</p></div><div class="campaign-stamp"><span>{e(h['monthBadge'])}</span><strong>{e(h['systemLabel'])}</strong></div></div></section></div>'''


def render_try_it(c,icon):
    t=c['tryIt']
    chosen=int(t['defaultFraction']*100)
    decisions=''.join(f'<button type="button" data-keep="{int(d["fraction"]*100)}" aria-pressed="{str(int(d["fraction"]*100)==chosen).lower()}">{e(d["label"])}</button>' for d in t['decisions'])
    steps=''.join(f'<label class="starting-step"><input type="checkbox" data-plan-step="{i}"><span class="step-check" aria-hidden="true">{icon("tick")}</span><span>{e(text)}</span></label>' for i,text in enumerate(t['steps']))
    initial=t['defaultAmount']*t['annualTimes'][t['defaultFrequency']]
    return f'''<section class="try-section section-space" id="try-it"><div class="wrap"><div class="center-heading" data-reveal><p class="eyebrow">{e(t['eyebrow'])}</p><h2>{e(t['heading'])}</h2><p class="section-intro">{e(t['intro'])}</p></div><div class="try-layout" data-demo>
    <div class="demo-controls"><div class="demo-cost-row"><label for="demo-amount">{e(t['amountLabel'])}</label><div class="amount-input"><span aria-hidden="true">{e(t['currencySymbol'])}</span><input id="demo-amount" type="number" min="{t['rangeMin']}" max="{t['rangeMax']}" step="1" value="{t['defaultAmount']}" inputmode="decimal" aria-describedby="amount-help"></div></div><label class="sr-only" for="demo-range">{e(t['amountLabel'])}</label><input id="demo-range" class="cost-range" type="range" min="{t['rangeMin']}" max="{t['rangeMax']}" step="1" value="{t['defaultAmount']}" aria-describedby="amount-help"><p id="amount-help" class="demo-help">{e(t['amountNote'])}</p><p class="control-label">{e(t['frequencyLabel'])}</p><div class="frequency-buttons" role="group" aria-label="{e(t['frequencyLabel'])}"><button type="button" data-frequency="monthly" aria-pressed="true">{e(t['monthly'])}</button><button type="button" data-frequency="weekly" aria-pressed="false">{e(t['weekly'])}</button></div><div class="annual-result"><span>{e(t['annualLabel'])}</span><div><output id="annual-cost" for="demo-amount demo-range">${initial:,.0f}</output><span>{e(t['annualSuffix'])}</span></div></div><p class="control-label">{e(t['decisionLabel'])}</p><div class="decision-buttons" role="group" aria-label="{e(t['decisionLabel'])}">{decisions}</div><div class="retained-result"><div><span>{e(t['retainedLabel'])}</span><output id="retained-cost" for="demo-amount demo-range">${initial*t['defaultFraction']:,.0f}</output></div><p>{e(t['retainedNote'])}</p></div><p class="demo-disclaimer">{e(t['demoNote'])}</p></div>
    <div class="demo-visual"><span class="demo-orbit" aria-hidden="true"></span><img data-life src="assets/alicia-money-v3.webp" alt="{e(t['illustrationAlt'])}" width="800" height="960" loading="lazy"><div class="coin-meter" aria-hidden="true">{''.join('<i></i>' for _ in range(12))}</div></div>
    </div><div class="starting-plan"><div><p class="eyebrow">{e(c['hero']['from'])}</p><h3>{e(t['planHeading'])}</h3><p>{e(t['planIntro'])}</p></div><div class="plan-actions">{steps}<div class="plan-status"><span id="plan-progress">{e(t['planProgress'].replace('{count}','0').replace('{total}',str(len(t['steps']))))}</span><div class="plan-meter" aria-hidden="true"><i></i></div></div><button class="button" type="button" data-save-plan>{e(t['download'])}{icon('arrow')}</button><p class="demo-help" id="save-status" role="status">{e(t['privacy'])}</p></div></div><noscript><p class="demo-disclaimer">{e(t['noScript'])}</p></noscript></div></section>'''


def render_campaign_note(c):
    n=c['note']
    return f'''<section class="note-section note-v3 section-space"><div class="wrap note-v3-inner" data-reveal><div class="note-desk-art">{render_tea()}</div><div class="note-copy"><p class="eyebrow">{e(n['eyebrow'])}</p><blockquote>{e(n['body'])}</blockquote><p class="signature">{e(n['signature'])}<span aria-hidden="true">♡</span></p></div></div></section>'''
